GRANT INSERT ON public."Department" TO callzup_app;
GRANT UPDATE (name) ON public."Department" TO callzup_app;
DROP POLICY IF EXISTS callzup_department_insert ON public."Department";
DROP POLICY IF EXISTS callzup_department_update ON public."Department";
CREATE POLICY callzup_department_insert ON public."Department" FOR INSERT TO callzup_app WITH CHECK ("companyId"=public.callzup_empresa_atual() AND EXISTS (SELECT 1 FROM public."User" u WHERE u.id=public.callzup_usuario_atual() AND u."companyId"="Department"."companyId" AND u.role='IT_ADMIN' AND u.status='ACTIVE') AND EXISTS (SELECT 1 FROM public."Company" c WHERE c.id="Department"."companyId" AND c.status='ACTIVE') AND char_length(btrim(name)) BETWEEN 1 AND 150);
CREATE POLICY callzup_department_update ON public."Department" FOR UPDATE TO callzup_app USING ("companyId"=public.callzup_empresa_atual() AND EXISTS (SELECT 1 FROM public."User" u WHERE u.id=public.callzup_usuario_atual() AND u."companyId"="Department"."companyId" AND u.role='IT_ADMIN' AND u.status='ACTIVE') AND EXISTS (SELECT 1 FROM public."Company" c WHERE c.id="Department"."companyId" AND c.status='ACTIVE')) WITH CHECK ("companyId"=public.callzup_empresa_atual() AND EXISTS (SELECT 1 FROM public."User" u WHERE u.id=public.callzup_usuario_atual() AND u."companyId"="Department"."companyId" AND u.role='IT_ADMIN' AND u.status='ACTIVE') AND EXISTS (SELECT 1 FROM public."Company" c WHERE c.id="Department"."companyId" AND c.status='ACTIVE') AND char_length(btrim(name)) BETWEEN 1 AND 150);
